import numpy as np
from collections import defaultdict
from typing import List, Dict, Any, Tuple

class Project:
    def __init__(self, project_id: str, base_reward: float, resource_needed: int, current_resources: int = 0):
        self.project_id = project_id
        self.base_reward = base_reward
        self.resource_needed = resource_needed
        self.current_resources = current_resources
        self.completed = False

    def add_resources(self, amount: int):
        self.current_resources += amount
        if self.current_resources >= self.resource_needed and not self.completed:
            self.completed = True
            print(f"    Project {self.project_id} completed!")

    def get_reward(self) -> float:
        if self.completed:
            return self.base_reward
        return 0

    def reset_for_new_round(self):
        self.current_resources = 0
        self.completed = False

class ResourceAllocatingAgent:
    def __init__(self, agent_id: str, all_agent_ids: List[str], learning_rate: float = 0.1, epsilon_start: float = 0.3, epsilon_end: float = 0.05, mutation_rate: float = 0.05):
        self.agent_id = agent_id
        self.all_agent_ids = all_agent_ids
        self.total_reward = 0
        self.current_round_reward = 0
        self.learning_rate = learning_rate
        self.epsilon_start = epsilon_start
        self.epsilon_end = epsilon_end
        self.mutation_rate = mutation_rate

        # Strategy for allocating resources: maps project_id -> {'value_est': X, 'allocation_prob': Y}
        self.allocation_strategy = defaultdict(lambda: {'success': 1, 'attempts': 2, 'value_est': 0.5, 'allocation_prob': 0.1}) 
        self.reputations = {aid: 0.5 for aid in all_agent_ids if aid != agent_id}

        print(f"Resource Allocating Agent {self.agent_id} initialized.")

    def _get_epsilon(self, current_round: int, total_rounds: int) -> float:
        decay_rate = (self.epsilon_start - self.epsilon_end) / total_rounds
        return max(self.epsilon_end, self.epsilon_start - decay_rate * current_round)

    def choose_allocation(self, available_resource: int, projects: Dict[str, Project], current_round: int, total_rounds: int) -> Dict[str, int]:
        current_epsilon = self._get_epsilon(current_round, total_rounds)
        allocations = defaultdict(int)

        if np.random.rand() < current_epsilon:
            # Explore: random allocation
            for _ in range(available_resource):
                chosen_project = np.random.choice(list(projects.keys()))
                allocations[chosen_project] += 1
        else:
            # Exploit: allocate based on learned value estimates
            project_ids = list(projects.keys())
            # Calculate allocation probabilities based on value estimates
            total_value = sum(self.allocation_strategy[pid]['value_est'] for pid in project_ids)
            if total_value == 0:
                probs = np.ones(len(project_ids)) / len(project_ids)
            else:
                probs = np.array([self.allocation_strategy[pid]['value_est'] / total_value for pid in project_ids])

            for _ in range(available_resource):
                chosen_project_id = np.random.choice(project_ids, p=probs)
                allocations[chosen_project_id] += 1

        return allocations

    def update_learning(self, my_allocations: Dict[str, int], collective_rewards: Dict[str, float], all_project_rewards: Dict[str, float]):
        total_collective_reward_this_round = sum(collective_rewards.values())
        my_personal_contribution_reward = 0
        for project_id, allocated_amount in my_allocations.items():
            if allocated_amount > 0 and project_id in all_project_rewards:
                # For simplicity, if project completed, I get a share of its reward proportional to my allocation
                # More realistically, the reward is based on the final outcome, not just my individual part
                # Let's simplify to: if total_collective_reward_this_round is good, my strategy was good.
                my_personal_contribution_reward += all_project_rewards.get(project_id, 0) # Just see if project I allocated to was successful

        self.current_round_reward = total_collective_reward_this_round # Agent's "reward" for learning purposes is collective reward

        # Update allocation strategy based on collective outcome
        is_successful_round = total_collective_reward_this_round > 0 # A positive collective reward means success

        for project_id, data in self.allocation_strategy.items():
            self.allocation_strategy[project_id]['attempts'] += 1
            if is_successful_round and project_id in my_allocations and my_allocations[project_id] > 0:
                self.allocation_strategy[project_id]['success'] += 1

            # Value estimate updates based on overall round success, not just individual project
            # A more nuanced approach would be to assign blame/credit
            # Here, we simplify: high collective reward means my contribution was likely good.
            self.allocation_strategy[project_id]['value_est'] = \
                (1 - self.learning_rate) * self.allocation_strategy[project_id]['value_est'] + \
                self.learning_rate * (total_collective_reward_this_round / (len(self.all_agent_ids) * 5.0)) # Normalize to roughly 0-1

        self.total_reward += total_collective_reward_this_round

    def update_reputation_from_round_outcome(self, all_agents_collective_rewards: Dict[str, float]):
        """Updates reputation of others based on their perceived effectiveness in achieving collective reward."""
        for agent_id, reward in all_agents_collective_rewards.items():
            if agent_id == self.agent_id: continue

            scaled_reward_factor = (reward - (-len(self.all_agent_ids) * 3)) / (len(self.all_agent_ids) * 5 - (-len(self.all_agent_ids) * 3)) * 2 - 1 
            self.reputations[agent_id] = np.clip(self.reputations[agent_id] + self.learning_rate * scaled_reward_factor * 0.5, 0, 1)

    def consider_strategy_adoption(self, all_agents: Dict[str, 'ResourceAllocatingAgent'], current_round: int, total_rounds: int,
                                   adoption_threshold_self_reward_factor: float = 0.5, 
                                   adoption_threshold_other_rep: float = 0.8, 
                                   top_n_percent_mentors: float = 0.25):
        """
        Agent considers adopting strategy from top X% highly successful/reputable agents if its own reward is low.
        """
        max_possible_collective_reward_per_round = sum(p.base_reward for p in env.projects.values()) # Max for env
        expected_total_reward_for_current_round = max_possible_collective_reward_per_round * (current_round + 1)

        dynamic_self_reward_threshold = expected_total_reward_for_current_round * adoption_threshold_self_reward_factor

        if self.total_reward < dynamic_self_reward_threshold: 
            sorted_agents = sorted(all_agents.values(), key=lambda a: a.total_reward, reverse=True)
            num_top_mentors = max(1, int(len(self.all_agent_ids) * top_n_percent_mentors))

            potential_mentors = []
            for mentor_candidate in sorted_agents[:num_top_mentors]: 
                if mentor_candidate.agent_id == self.agent_id: continue

                if self.reputations.get(mentor_candidate.agent_id, 0.0) >= adoption_threshold_other_rep:
                    potential_mentors.append(mentor_candidate)

            if potential_mentors:
                mentor = max(potential_mentors, key=lambda a: a.total_reward)
                print(f"  Agent {self.agent_id} (Total Reward {self.total_reward:.2f}) adopting strategy from {mentor.agent_id} (Total Reward {mentor.total_reward:.2f}).")

                self.allocation_strategy = {k: v.copy() for k, v in mentor.allocation_strategy.items()}

                if np.random.rand() < self.mutation_rate:
                    print(f"    Agent {self.agent_id} mutates adopted strategy.")
                    for pid in self.allocation_strategy.keys():
                        self.allocation_strategy[pid]['value_est'] = np.clip(self.allocation_strategy[pid]['value_est'] + np.random.uniform(-0.1, 0.1), 0, 1)

                self.epsilon_start = 0.3 

class ResourceAllocationEnvironment:
    def __init__(self, num_agents: int, num_projects: int = 3, total_resource_per_round: int = 10):
        self.num_agents = num_agents
        self.total_resource_per_round = total_resource_per_round
        self.projects = {}

        # Initialize projects with varying requirements and rewards
        self.projects['Project_A'] = Project('Project_A', base_reward=10, resource_needed=5)
        self.projects['Project_B'] = Project('Project_B', base_reward=15, resource_needed=7)
        self.projects['Project_C'] = Project('Project_C', base_reward=8, resource_needed=4)

        print(f"Environment initialized for {num_agents} agents, {len(self.projects)} projects, {total_resource_per_round} resources/round.")

    def distribute_and_resolve(self, collective_allocations: Dict[str, int]) -> Tuple[Dict[str, float], Dict[str, float]]:
        # Reset project resources for the round
        for project in self.projects.values():
            project.reset_for_new_round()

        # Add resources from agents' allocations
        for project_id, amount in collective_allocations.items():
            if project_id in self.projects:
                self.projects[project_id].add_resources(amount)

        current_project_rewards = {}
        for project_id, project in self.projects.items():
            current_project_rewards[project_id] = project.get_reward()

        total_collective_reward = sum(current_project_rewards.values())

        print(f"    Round Resolution: Projects completed {[p.project_id for p in self.projects.values() if p.completed]}, Collective Reward: {total_collective_reward}")

        return current_project_rewards, total_collective_reward

# --- Simulation Setup ---
NUM_AGENTS = 5
NUM_ROUNDS = 250 
TOTAL_RESOURCE_PER_ROUND = 10 # Shared resource pool for all agents

all_agent_ids = [f"Agent_{i+1}" for i in range(NUM_AGENTS)]

agents_dict = {}
for aid in all_agent_ids:
    agents_dict[aid] = ResourceAllocatingAgent(aid, all_agent_ids, learning_rate=0.2, epsilon_start=0.3, epsilon_end=0.05, mutation_rate=0.05)

env = ResourceAllocationEnvironment(NUM_AGENTS, total_resource_per_round=TOTAL_RESOURCE_PER_ROUND)

print(f"\n--- Starting {NUM_ROUNDS} Rounds of Cultural Evolution Framework - Decentralized Resource Allocation Game ---")

for i in range(NUM_ROUNDS):
    print(f"\nRound {i+1} / {NUM_ROUNDS}")
    individual_allocations_this_round = {}

    # Each agent decides its allocation given the total available resource
    for agent_id in all_agent_ids:
        individual_allocations_this_round[agent_id] = agents_dict[agent_id].choose_allocation(
            TOTAL_RESOURCE_PER_ROUND // NUM_AGENTS, # Each agent gets a share of total resource
            env.projects, 
            i, NUM_ROUNDS
        )

    # Aggregate all agents' allocations to get collective allocation for projects
    collective_allocations_for_round = defaultdict(int)
    for agent_id, agent_allocations in individual_allocations_this_round.items():
        for project_id, amount in agent_allocations.items():
            collective_allocations_for_round[project_id] += amount

    project_rewards, total_collective_reward = env.distribute_and_resolve(collective_allocations_for_round)

    agents_collective_rewards_map = {} # Map for reputation update based on total
    for agent_id in all_agent_ids:
        agent = agents_dict[agent_id]
        agent.update_learning(
            my_allocations=individual_allocations_this_round[agent_id],
            collective_rewards={aid: total_collective_reward for aid in all_agent_ids}, # All agents share the collective outcome
            all_project_rewards=project_rewards
        )
        agents_collective_rewards_map[agent_id] = total_collective_reward

    for agent_id in all_agent_ids:
        agents_dict[agent_id].update_reputation_from_round_outcome(agents_collective_rewards_map)

    if (i + 1) % 25 == 0: 
        print(f"\n--- Cultural Transmission Check (Round {i+1}) ---")
        for agent_id in all_agent_ids:
            agents_dict[agent_id].consider_strategy_adoption(agents_dict, current_round=i, total_rounds=NUM_ROUNDS,
                                                           adoption_threshold_self_reward_factor=0.5, 
                                                           adoption_threshold_other_rep=0.8, 
                                                           top_n_percent_mentors=0.25)

        print(f"\nRound {i+1} Summary (Collective Reward: {total_collective_reward}, Epsilon: {agents_dict[all_agent_ids[0]]._get_epsilon(i, NUM_ROUNDS):.2f}):")
        for agent_id in all_agent_ids:
            agent = agents_dict[agent_id]
            print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
            for pid, data in agent.allocation_strategy.items():
                print(f"    {pid} Est: {data['value_est']:.2f}")
            for rep_partner_id, rep_score in agent.reputations.items():
                print(f"    Rep for {rep_partner_id}: {rep_score:.2f}")

print(f"\n--- Simulation Complete ---")
print("\nFinal Agent Rewards:")
for agent_id in all_agent_ids:
    agent = agents_dict[agent_id]
    print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
    for pid, data in agent.allocation_strategy.items():
        print(f"    {pid} Est: {data['value_est']:.2f}")
    for rep_partner_id, rep_score in agent.reputations.items():
        print(f"    Rep for {rep_partner_id}: {rep_score:.2f}")

final_collective_reward = sum(agent.total_reward for agent in agents_dict.values())
print(f"Final Collective Reward (sum of individual totals): {final_collective_reward}")
